// WithEndpoint configures the metrics host and port only; endpoint should
// resemble "example.com" or "localhost:4317". To configure the scheme and
// path, use WithEndpointURL.
func WithEndpoint(endpoint string) GenericOption {
	return newGenericOption(func(cfg Config) Config {
		cfg.Metrics.Endpoint = endpoint
		return cfg
	})
}

// WithEndpointURL configures the metrics scheme, host, port, and path; the
// provided value should resemble "https://example.com:4318/v1/metrics".
func WithEndpointURL(v string) GenericOption {
	return newGenericOption(func(cfg Config) Config {
		u, err := url.Parse(v)
		if err != nil {
			global.Error(err, "otlpmetric: parse endpoint url", "url", v)
			return cfg
		}

		cfg.Metrics.Endpoint = u.Host
		cfg.Metrics.URLPath = u.Path
		cfg.Metrics.URLRawPath = u.RawPath
		if cfg.Metrics.URLPath == "" {
			// For HTTP exporters, a URL without a path targets the root path.
			// URLPath is ignored by gRPC exporters.
			cfg.Metrics.URLPath = "/"
		}
		cfg.Metrics.Insecure = u.Scheme != "https"

		return cfg
	})
}

